function V({registerIndicator:C,nulls:w}){const x=Math.sqrt(252),S=1e-10;C({id:"oa-ccv",name:"Close-to-Close Volatility (CCV)",category:"Volatility",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:20,min:1,max:500,step:1,tooltip:"Number of bars for volatility calculation."},{key:"method",type:"number",label:"Method",default:1,min:1,max:3,step:1,tooltip:"1 = SMA, 2 = EMA, 3 = WMA. Method 3 reduces to method 1 in the source formula."}],plots:[{key:"ccv",type:"line",title:"CCV",style:{color:"#ffeb3b",lineWidth:2}}],calc(i,p){const t=Math.max(1,Math.min(500,Math.floor(Number(p.length)||20))),M=Math.max(1,Math.min(3,Math.floor(Number(p.method)||1))),o=Math.max(1,t),m=new Array(o).fill(NaN);let a=0,c=0;const k=0;let s=0,u=1;const A=1-1/t,b=Math.floor(t*(t+1)/2),r=new Array(i.length).fill(NaN);for(let e=0;e<i.length;e++){const f=i[e].close,N=e>0?i[e-1].close:NaN;let y=NaN;Number.isFinite(f)&&Number.isFinite(N)&&f>0&&N>0&&(y=Math.log(f/N)),Number.isFinite(m[a])&&(c-=1),c+=1,m[a]=y,a=(a+1)%o;let g=0;for(let l=0;l<t;l++){const n=m[((a-l-1)%o+o)%o];Number.isFinite(n)&&(g+=Math.pow(n-k,2))}const d=c>0?Math.sqrt(g/c)*x:NaN;let h=NaN;if(M===1)h=d;else if(M===2)s=(s*(t-1)+d)/t,u*=A,h=u>S?s/(1-u):s;else{let l=0,n=t;for(let v=0;v<t;v++)l+=d*n,n-=1;h=b>0?l/b:NaN}r[e]=h}return r.length>0&&(r[0]=NaN),{ccv:w(r)}}})}export{V as default};
